 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    if not markers:
        return out
    r, c = markers[0]
    # The pointer is on the edge and emits a ray inward.
    if r == 0:
        direction = (1, 0)
    elif r == h - 1:
        direction = (-1, 0)
    elif c == 0:
        direction = (0, 1)
    elif c == w - 1:
        direction = (0, -1)
    else:
        return out

    dr, dc = direction
    queue = deque([(r, c, dr, dc)])
    seen = set()

    def inside(a, b):
        return 0 <= a < h and 0 <= b < w

    def paint(a, b):
        if grid[a][b] == 0:
            out[a][b] = 2

    while queue:
        r, c, dr, dc = queue.popleft()
        while True:
            state = (r, c, dr, dc)
            if state in seen:
                break
            seen.add(state)
            nr, nc = r + dr, c + dc
            if not inside(nr, nc):
                break
            if grid[nr][nc] != 8:
                paint(nr, nc)
                r, c = nr, nc
                continue

            # A ray striking an 8 barrier spreads sideways along its edge.
            # It continues across the barrier's length until it finds a gap,
            # where a new ray proceeds in the original direction.
            side_dirs = [(-dc, dr), (dc, -dr)]
            for sdr, sdc in side_dirs:
                ar, ac = r, c
                while True:
                    qr, qc = ar + sdr, ac + sdc
                    if not inside(qr, qc):
                        break
                    paint(qr, qc)
                    br, bc = qr + dr, qc + dc
                    if not inside(br, bc) or grid[br][bc] != 8:
                        queue.append((qr, qc, dr, dc))
                        break
                    ar, ac = qr, qc
            break
    return out


if __name__ == "__main__":
    import json, sys
    print(json.dumps(transform(json.loads(sys.stdin.read()))))
